#include <stdio.h>
#include <math.h>

int main(void)
{
    double a = 0.1 + 0.2;

    printf("%.1f\n", a);                /* rounded for display */
    printf("%.17f\n", a);               /* what is really stored */
    printf("equal: %d\n", a == 0.3);    /* 1 would mean true */
    printf("close: %d\n", fabs(a - 0.3) < 1e-9);

    float f = 1.0f / 3.0f;
    printf("float  %.10f\n", f);
    printf("double %.10f\n", 1.0 / 3.0);
    return 0;
}

#include <stdio.h>
#include <stdbool.h>

int main(void)
{
    char letter = 'A';
    bool big = 10 > 3;

    printf("%c is %d\n", letter, letter);
    printf("next: %c\n", letter + 1);
    printf("lower: %c\n", letter + ('a' - 'A'));
    printf("big = %d\n", big);
    printf("sizeof(bool) = %zu\n", sizeof(bool));
    return 0;
}

#include <stdio.h>

int main(void)
{
    int a = 7, b = 2;

    printf("%d\n", a / b);             /* integer division */
    printf("%d\n", a % b);             /* remainder */
    printf("%.1f\n", (double)a / b);   /* cast first: 3.5 */
    printf("%.1f\n", (double)(a / b)); /* cast too late: 3.0 */

    double d = 9.99;
    int truncated = d;                 /* fraction dropped, not rounded */
    printf("%d\n", truncated);

    unsigned int u = 0;
    u = u - 1;                         /* wraps around */
    printf("%u\n", u);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n = -1;
    unsigned int limit = 1;

    if (n < limit)
        printf("n is smaller\n");
    else
        printf("n is NOT smaller: it became %u\n", n);
    return 0;
}
